export class ConfError extends Error {}

const BARE = /[A-Za-z0-9_-]/
const isWs = (c) => c === ' ' || c === '\t'
const T = (map) => ({ t: 'table', map, hdr: false })

function fail(msg) { throw new ConfError(msg) }

class Line {
  constructor(s) { this.s = s; this.i = 0 }
  get c() { return this.s[this.i] }
  ws() { while (isWs(this.s[this.i])) this.i++ }
  atEnd() { return this.i >= this.s.length }
  atComment() { return this.c === '#' || this.c === ';' }
  tailOk() { this.ws(); return this.atEnd() || this.atComment() }

  basicString() {
    this.i++
    let out = ''
    for (;;) {
      if (this.atEnd()) fail('unterminated string')
      const c = this.c
      this.i++
      if (c === '"') return out
      if (c !== '\\') { out += c; continue }
      if (this.atEnd()) fail('unterminated string')
      const e = this.c
      this.i++
      if (e === '"') out += '"'
      else if (e === '\\') out += '\\'
      else if (e === 'n') out += '\n'
      else if (e === 't') out += '\t'
      else if (e === 'r') out += '\r'
      else if (e === '0') out += '\0'
      else if (e === 'u') {
        const h = this.s.slice(this.i, this.i + 4)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        this.i += 4
      } else fail('invalid escape \\' + String.fromCodePoint(e.codePointAt(0) === e.charCodeAt(0) ? e.charCodeAt(0) : e.codePointAt(0)))
    }
  }

  literalString() {
    const j = this.s.indexOf("'", this.i + 1)
    if (j < 0) fail('unterminated string')
    const r = this.s.slice(this.i + 1, j)
    this.i = j + 1
    return r
  }

  name() {
    const c = this.c
    if (c === '"') return this.basicString()
    if (c === "'") return this.literalString()
    const st = this.i
    while (!this.atEnd() && BARE.test(this.c)) this.i++
    if (st === this.i) fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted() {
    const names = []
    this.ws()
    names.push(this.name())
    for (;;) {
      const save = this.i
      this.ws()
      if (this.c === '.') {
        this.i++
        this.ws()
        names.push(this.name())
      } else { this.i = save; return names }
    }
  }

  value() {
    this.ws()
    if (this.atEnd() || this.atComment() || ',]}'.includes(this.c)) fail('expected a value')
    const c = this.c
    if (c === '"') return { t: 'string', v: this.basicString() }
    if (c === "'") return { t: 'string', v: this.literalString() }
    if (c === '[') return this.array()
    if (c === '{') return this.inline()
    const st = this.i
    while (!this.atEnd() && !isWs(this.c) && !',]};'.includes(this.c)) this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true') return { t: 'boolean', v: true }
    if (w === 'false') return { t: 'boolean', v: false }
    const D = '\\d+(?:_\\d+)*'
    if (new RegExp(`^[+-]?${D}$`).test(w)) return { t: 'integer', v: Number(w.replace(/_/g, '')) }
    if (new RegExp(`^[+-]?${D}(?:\\.${D}(?:[eE][+-]?${D})?|[eE][+-]?${D})$`).test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
    fail('invalid value ' + w)
  }

  array() {
    this.i++
    const items = []
    for (;;) {
      this.ws()
      if (this.atEnd() || this.atComment()) fail('unterminated array')
      if (this.c === ']') { this.i++; return { t: 'array', items, aot: false } }
      items.push(this.value())
      this.ws()
      if (this.c === ',') { this.i++; continue }
      if (this.c === ']') { this.i++; return { t: 'array', items, aot: false } }
      fail('unterminated array')
    }
  }

  inline() {
    this.i++
    const tbl = T(new Map())
    this.ws()
    if (this.c === '}') { this.i++; return tbl }
    for (;;) {
      this.ws()
      if (this.atEnd() || this.atComment()) fail('unterminated inline table')
      const names = this.dotted()
      this.ws()
      if (this.c !== '=') fail('expected = in an inline table')
      this.i++
      const v = this.value()
      assign(tbl, [], names, v)
      this.ws()
      if (this.c === ',') { this.i++; continue }
      if (this.c === '}') { this.i++; return tbl }
      fail('unterminated inline table')
    }
  }
}

// Descend through `names` from `tbl`, creating tables. Returns the table reached.
function walk(tbl, base, names) {
  const path = [...base]
  for (const n of names) {
    path.push(n)
    let cur = tbl.map.get(n)
    if (!cur) { cur = T(new Map()); tbl.map.set(n, cur) }
    if (cur.t === 'array' && cur.aot) cur = cur.items[cur.items.length - 1]
    if (cur.t !== 'table') fail(`${path.join('.')} is not a table`)
    tbl = cur
  }
  return tbl
}

function assign(tbl, base, names, v) {
  const parent = walk(tbl, base, names.slice(0, -1))
  const last = names[names.length - 1]
  if (parent.map.has(last)) fail(`key ${[...base, ...names].join('.')} is defined twice`)
  parent.map.set(last, v)
}

function header(root, names, isArr) {
  const parent = walk(root, [], names.slice(0, -1))
  const last = names[names.length - 1]
  const path = names.join('.')
  const ex = parent.map.get(last)
  if (isArr) {
    if (!ex) {
      const t = T(new Map())
      parent.map.set(last, { t: 'array', items: [t], aot: true })
      return t
    }
    if (ex.t !== 'array' || !ex.aot) fail(`${path} is not an array of tables`)
    const t = T(new Map())
    ex.items.push(t)
    return t
  }
  if (!ex) {
    const t = T(new Map())
    t.hdr = true
    parent.map.set(last, t)
    return t
  }
  if (ex.t !== 'table') fail(`${path} is not a table`)
  if (ex.hdr) fail(`table ${path} is defined twice`)
  ex.hdr = true
  return ex
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = T(new Map())
  let cur = root
  let curPath = []
  lines.forEach((raw, idx) => {
    try {
      const L = new Line(raw)
      L.ws()
      if (L.atEnd() || L.atComment()) return
      if (L.c === '[') {
        const isArr = raw[L.i + 1] === '['
        L.i += isArr ? 2 : 1
        const names = L.dotted()
        L.ws()
        if (L.c !== ']') fail('unterminated table header')
        L.i++
        if (isArr) {
          if (L.c !== ']') fail('unterminated table header')
          L.i++
        }
        if (!L.tailOk()) fail('trailing text after a table header')
        cur = header(root, names, isArr)
        curPath = names
        return
      }
      const names = L.dotted()
      L.ws()
      if (L.c !== '=') fail('expected key = value')
      L.i++
      const v = L.value()
      if (!L.tailOk()) fail('trailing text after a value')
      assign(cur, curPath, names, v)
    } catch (e) {
      if (e instanceof ConfError) e.message = `line ${idx + 1}: ${e.message}`
      throw e
    }
  })
  return root
}
