import { readFileSync } from 'node:fs'

class Fail extends Error {}
const fail = (m) => { throw new Fail(`error: ${m}`) }

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  let cands = null
  const ballots = []
  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const t = line.split(/\s+/)
    if (t[0] === 'candidates') {
      if (cands !== null || ballots.length) fail(`line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 2) fail(`line ${n}: expected candidates <name>...`)
      const seen = new Set()
      for (const name of t.slice(1)) {
        if (!/^[A-Za-z0-9_-]+$/.test(name)) fail(`line ${n}: invalid candidate name ${name}`)
        if (seen.has(name)) fail(`line ${n}: candidate ${name} is declared twice`)
        seen.add(name)
      }
      cands = t.slice(1)
    } else if (t[0] === 'ballot') {
      if (cands === null) fail(`line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 3) fail(`line ${n}: expected ballot <count> <candidate>...`)
      if (!/^[1-9][0-9]*$/.test(t[1])) fail(`line ${n}: count must be a positive integer`)
      const seen = new Set()
      for (const name of t.slice(2)) {
        if (!cands.includes(name)) fail(`line ${n}: unknown candidate ${name}`)
        if (seen.has(name)) fail(`line ${n}: candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: Number(t[1]), prefs: t.slice(2) })
    } else {
      fail(`line ${n}: unknown directive ${t[0]}`)
    }
  })
  if (cands === null) fail('no candidates')
  return { cands, ballots }
}

function run(cands, ballots) {
  const continuing = new Set(cands)
  const history = [] // Map per round
  const out = []
  let rounds = 0
  let winner = null
  for (;;) {
    rounds++
    const counts = new Map([...continuing].map((c) => [c, 0]))
    let active = 0
    for (const b of ballots) {
      const c = b.prefs.find((p) => continuing.has(p))
      if (c !== undefined) { counts.set(c, counts.get(c) + b.count); active += b.count }
    }
    history.push(counts)
    const total = ballots.reduce((s, b) => s + b.count, 0)
    const sorted = [...counts].sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
    let line = `round ${rounds}: ${sorted.map(([c, v]) => `${c}=${v}`).join(' ')} exhausted=${total - active}`
    out.push(line)
    if (active === 0) break
    const top = sorted.find(([, v]) => v * 2 > active)
    if (top) { winner = top[0]; break }
    let tied = [...continuing]
    const min = Math.min(...tied.map((c) => counts.get(c)))
    tied = tied.filter((c) => counts.get(c) === min)
    for (let r = 0; r < history.length && tied.length > 1; r++) {
      const vals = tied.map((c) => history[r].get(c))
      const m = Math.min(...vals)
      if (vals.some((v) => v !== m)) tied = tied.filter((c) => history[r].get(c) === m)
    }
    let elim = tied[0]
    for (const c of tied) if (c > elim) elim = c
    continuing.delete(elim)
    out.push(`eliminated ${elim}`)
  }
  return { out, rounds, winner }
}

try {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'rounds' && argv[0] !== 'tally')) fail('usage: cli.js rounds|tally')
  const { cands, ballots } = parse(readFileSync(0, 'utf8'))
  const r = run(cands, ballots)
  const tail = r.winner === null ? 'no winner' : `winner ${r.winner}`
  const lines = argv[0] === 'rounds' ? r.out : [`rounds ${r.rounds}`]
  process.stdout.write([...lines, tail].join('\n') + '\n')
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exitCode = 2
}
EOF
