/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */
import { readFileSync } from 'node:fs'

class Fail extends Error {
  constructor(message, code = 2) {
    super(message)
    this.code = code
  }
}

const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const costs = new Map()
  const deps = new Map()
  const used = []
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const w = line.split(/\s+/)
    const n = i + 1
    if (w[0] === 'task') {
      if (w.length !== 3) throw new Fail(`error: line ${n}: expected task <name> <cost>`)
      if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) throw new Fail(`error: line ${n}: invalid task name ${w[1]}`)
      if (!/^[0-9]+$/.test(w[2])) throw new Fail(`error: line ${n}: cost must be a non-negative integer`)
      if (costs.has(w[1])) throw new Fail(`error: line ${n}: task ${w[1]} is declared twice`)
      costs.set(w[1], BigInt(w[2]))
    } else if (w[0] === 'dep') {
      if (w.length < 3) throw new Fail(`error: line ${n}: expected dep <name> <dependency>...`)
      for (const x of w.slice(1)) used.push(x)
      if (!deps.has(w[1])) deps.set(w[1], new Set())
      for (const d of w.slice(2)) deps.get(w[1]).add(d)
    } else {
      throw new Fail(`error: line ${n}: unknown directive ${w[0]}`)
    }
  })
  for (const x of used) if (!costs.has(x)) throw new Fail(`error: unknown task ${x}`)
  const names = [...costs.keys()].sort(cmp)
  const dmap = new Map(names.map((k) => [k, [...(deps.get(k) ?? [])].sort(cmp)]))
  return { names, costs, deps: dmap }
}

function checkCycle({ names, deps }) {
  const state = new Map()
  const stack = []
  const visit = (u) => {
    state.set(u, 1)
    stack.push(u)
    for (const v of deps.get(u)) {
      const s = state.get(v)
      if (s === 1) {
        const cyc = stack.slice(stack.indexOf(v))
        cyc.push(v)
        throw new Fail(`error: cycle: ${cyc.join(' -> ')}`, 3)
      }
      if (!s) visit(v)
    }
    stack.pop()
    state.set(u, 2)
  }
  for (const k of names) if (!state.get(k)) visit(k)
}

function times(g) {
  const info = new Map()
  const go = (u) => {
    if (info.has(u)) return info.get(u)
    let start = 0n
    let depth = 0
    for (const d of g.deps.get(u)) {
      const x = go(d)
      if (x.finish > start) start = x.finish
      if (x.depth + 1 > depth) depth = x.depth + 1
    }
    const r = { start, finish: start + g.costs.get(u), depth }
    info.set(u, r)
    return r
  }
  for (const k of g.names) go(k)
  let total = 0n
  for (const r of info.values()) if (r.finish > total) total = r.finish
  return { info, total }
}

function pack(g, workers) {
  const prio = new Map()
  const rev = new Map(g.names.map((k) => [k, []]))
  for (const k of g.names) for (const d of g.deps.get(k)) rev.get(d).push(k)
  const pr = (u) => {
    if (prio.has(u)) return prio.get(u)
    let best = 0n
    for (const v of rev.get(u)) if (pr(v) > best) best = pr(v)
    const p = best + g.costs.get(u)
    prio.set(u, p)
    return p
  }
  g.names.forEach(pr)
  const finish = new Map()
  const free = new Array(workers).fill(0n)
  const runs = Array.from({ length: workers }, () => [])
  let pending = g.names.slice()
  let t = 0n
  let makespan = 0n
  while (pending.length) {
    for (;;) {
      let w = free.findIndex((f) => f <= t)
      if (w < 0) break
      let pick = null
      for (const k of pending) {
        if (!g.deps.get(k).every((d) => finish.has(d) && finish.get(d) <= t)) continue
        if (pick === null || prio.get(k) > prio.get(pick)) pick = k
      }
      if (pick === null) break
      const f = t + g.costs.get(pick)
      finish.set(pick, f)
      free[w] = f
      runs[w].push(`${pick}@${t}-${f}`)
      if (f > makespan) makespan = f
      pending = pending.filter((k) => k !== pick)
    }
    if (!pending.length) break
    let next = null
    for (const f of free) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
    t = next
  }
  const out = runs.map((r, i) => `worker ${i}:${r.map((x) => ' ' + x).join('')}`)
  out.push(`makespan ${makespan}`)
  return out
}

function main() {
  const [cmd, ...rest] = process.argv.slice(2)
  let workers = 0
  if (cmd === 'pack') {
    if (rest.length !== 1) throw new Fail('error: usage: cli.js waves|explain|pack <workers>')
    if (!/^[1-9][0-9]*$/.test(rest[0])) throw new Fail('error: workers must be a positive integer')
    workers = Number(rest[0])
  } else if ((cmd !== 'waves' && cmd !== 'explain') || rest.length) {
    throw new Fail('error: usage: cli.js waves|explain|pack <workers>')
  }
  let text = ''
  try {
    text = readFileSync(0, 'utf8')
  } catch {}
  const g = parse(text)
  checkCycle(g)
  if (cmd === 'pack') return pack(g, workers)
  const { info, total } = times(g)
  const out = []
  if (cmd === 'waves') {
    const byDepth = []
    for (const k of g.names) (byDepth[info.get(k).depth] ??= []).push(k)
    byDepth.forEach((ks, i) => out.push(`wave ${i}: ${ks.join(' ')}`))
  } else {
    for (const k of g.names) {
      const r = info.get(k)
      out.push(`${k} start=${r.start} finish=${r.finish} depth=${r.depth}`)
    }
  }
  out.push(`total ${total}`)
  return out
}

try {
  process.stdout.write(main().join('\n') + '\n')
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exitCode = e.code
}
"}

