  function argValues(a) {
    if (a.t === 'range') {
      if (!a.a || !a.b) return [err('#REF!')]
      return expand(a.a, a.b).map(cellValue)
    }
    return [ev(a)]
  }

  function ev(n) {
    switch (n.t) {
      case 'num': return num(n.v)
      case 'bool': return bool(n.v)
      case 'ref': return n.addr ? cellValue(n.addr) : err('#REF!')
      case 'range': return err('#ERR!')
      case 'un': {
        const e = ev(n.e)
        if (e.k === 'err') return e
        const x = toNum(e)
        if (x.k === 'err') return x
        return num(n.op === '-' ? -x.v : x.v)
      }
      case 'bin': return binary(n)
      case 'call': return call(n)
    }
  }

