const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'

function fail(line, col, message) {
  const e = new Error(message)
  e.scanError = true
  e.line = line
  e.col = col
  throw e
}

export function scan(text) {
  const s = Array.from(text)
  const n = s.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1

  const advance = () => {
    const c = s[i++]
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') {
      col = col - ((col - 1) % 4) + 4
    } else col++
    return c
  }

  // digits of one run, with single `_` between two digits
  const run = (ok) => {
    let j = i
    while (j < n && (ok(s[j]) || (s[j] === '_' && j > i && ok(s[j - 1]) && ok(s[j + 1])))) j++
    return j
  }

  while (i < n) {
    const c = s[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      advance()
      continue
    }
    const sl = line
    const sc = col
    const push = (kind, body) => tokens.push({ line: sl, col: sc, kind, body })

    if (c === '/' && s[i + 1] === '/') {
      while (i < n && s[i] !== '\n') advance()
      continue
    }
    if (c === '/' && s[i + 1] === '*') {
      let depth = 0
      do {
        if (i >= n) fail(sl, sc, 'unterminated block comment')
        if (s[i] === '/' && s[i + 1] === '*') {
          depth++
          advance()
          advance()
        } else if (s[i] === '*' && s[i + 1] === '/') {
          depth--
          advance()
          advance()
        } else advance()
      } while (depth > 0)
      continue
    }
    if (c === 'r' && s[i + 1] === '"') {
      let j = i + 2
      while (j < n && s[j] !== '"') j++
      if (j >= n) fail(sl, sc, 'unterminated string')
      const val = s.slice(i + 2, j).join('')
      while (i <= j) advance()
      push('rawstring', JSON.stringify(val))
      continue
    }
    if (isLetter(c) || c === '_') {
      let j = i
      while (j < n && isIdentChar(s[j])) j++
      const word = s.slice(i, j).join('')
      while (i < j) advance()
      push(KEYWORDS.has(word) ? 'keyword' : 'ident', word)
      continue
    }
    if (isDigit(c)) {
      let j
      let bad = false
      const p = (s[i + 1] || '').toLowerCase()
      const pred = p === 'x' ? isHex : p === 'b' ? isBin : p === 'o' ? isOct : null
