class ParseError extends Error {}
const fail = (m) => { throw new ParseError(m) }

const newTable = (header = false) => ({ t: 'table', m: new Map(), header })
const isWs = (c) => c === ' ' || c === '\t'
const BARE = /[A-Za-z0-9_-]/
const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

class LineParser {
  constructor(s) { this.s = s; this.i = 0 }
  ws() { while (isWs(this.s[this.i])) this.i++ }
  // at end of meaningful text (end of line or start of a comment)
  atEnd() { const c = this.s[this.i]; return c === undefined || c === '#' || c === ';' }

  string(q) {
    const s = this.s
    this.i++
    let out = ''
    if (q === "'") {
      const j = s.indexOf("'", this.i)
      if (j < 0) fail('unterminated string')
      out = s.slice(this.i, j)
      this.i = j + 1
      return out
    }
    for (;;) {
      const c = s[this.i]
      if (c === undefined) fail('unterminated string')
      if (c === '"') { this.i++; return out }
      if (c === '\\') {
        const e = s[this.i + 1]
        if (e === undefined) fail('unterminated string')
        const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (e in map) { out += map[e]; this.i += 2 } else if (e === 'u') {
          const h = s.slice(this.i + 2, this.i + 6)
          if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          this.i += 6
        } else fail('invalid escape \\' + String.fromCodePoint(s.codePointAt(this.i + 1)))
        continue
      }
      out += c
      this.i++
    }
  }

  name() {
    const c = this.s[this.i]
    if (c === '"' || c === "'") return this.string(c)
    const st = this.i
    while (this.i < this.s.length && BARE.test(this.s[this.i])) this.i++
    if (this.i === st) fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted() {
    const parts = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.s[this.i] === '.') {
        this.i++
        this.ws()
        parts.push(this.name())
      } else { this.i = save; break }
    }
    return parts
  }

  value() {
    const s = this.s
    const c = s[this.i]
    if (c === undefined || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"' || c === "'") return { t: 'string', v: this.string(c) }
    if (c === '[') {
      this.i++
      const items = []
      for (;;) {
        this.ws()
        if (this.atEnd()) fail('unterminated array')
        if (s[this.i] === ']') { this.i++; break }
        items.push(this.value())
        this.ws()
        if (s[this.i] === ',') { this.i++; continue }
        if (s[this.i] === ']') { this.i++; break }
        fail('unterminated array')
      }
      return { t: 'array', items, aot: false }
    }
    if (c === '{') {
      this.i++
      const tbl = newTable(true)
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      if (s[this.i] === '}') { this.i++; return tbl }
      for (;;) {
        this.ws()
        if (this.atEnd() && s[this.i] !== undefined) fail('unterminated inline table')
        if (this.s[this.i] === undefined) fail('unterminated inline table')
        const path = this.dotted()
        this.ws()
        if (s[this.i] !== '=') fail('expected = in an inline table')
        this.i++
        this.ws()
        const v = this.value()
        assign(tbl, [], path, v)
        this.ws()
        if (s[this.i] === ',') { this.i++; continue }
        if (s[this.i] === '}') { this.i++; break }
        fail('unterminated inline table')
      }
      return tbl
    }
    const st = this.i
    while (this.i < s.length && !isWs(s[this.i]) && !',]};'.includes(s[this.i])) this.i++
    const w = s.slice(st, this.i)
    if (w === 'true' || w === 'false') return { t: 'boolean', v: w === 'true' }
    if (INT.test(w)) return { t: 'integer', v: BigInt(w.replace(/_/g, '')).toString() }
    if (FLOAT.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
    fail('invalid value ' + w)
  }
}

// step into a child on a walk; returns the table to continue in
function descend(tbl, prefix, name, create) {
  const path = [...prefix, name]
  let n = tbl.m.get(name)
  if (n === undefined) {
    n = newTable()
    tbl.m.set(name, n)
  }
  if (n.t === 'table') return n
  if (n.t === 'array' && n.aot) return n.items[n.items.length - 1]
  fail(path.join('.') + ' is not a table')
}

function assign(cur, curPath, path, v) {
  let t = cur
  const pre = [...curPath]
