    t = descend(t, pre, path[k])
    pre.push(path[k])
  }
  const last = path[path.length - 1]
  if (t.m.has(last)) fail('key ' + [...pre, last].join('.') + ' is defined twice')
  t.m.set(last, v)
}

function parseDoc(text) {
  const root = newTable(true)
