        p.ws()
        const path = p.dotted()
        p.ws()
        if (line[p.i] !== ']') fail('unterminated table header')
        p.i++
        if (dbl) {
          if (line[p.i] !== ']') fail('unterminated table header')
          p.i++
        }
        p.ws()
        if (!p.atEnd()) fail('trailing text after a table header')
        let t = root
        const pre = []
        for (let k = 0; k < path.length - 1; k++) {
          t = descend(t, pre, path[k])
          pre.push(path[k])
        }
        const last = path[path.length - 1]
        const full = path.join('.')
        const n = t.m.get(last)
        if (dbl) {
          if (n === undefined) {
            cur = newTable(true)
            t.m.set(last, { t: 'array', items: [cur], aot: true })
          } else if (n.t === 'array' && n.aot) {
            cur = newTable(true)
            n.items.push(cur)
          } else fail(full + ' is not an array of tables')
        } else if (n === undefined) {
          cur = newTable(true)
          t.m.set(last, cur)
        } else if (n.t === 'table') {
          if (n.header) fail('table ' + full + ' is defined twice')
          n.header = true
          cur = n
        } else fail(full + ' is not a table')
        curPath = path
        return
      }
      const path = p.dotted()
      p.ws()
      if (line[p.i] !== '=') fail('expected key = value')
      p.i++
      p.ws()
      const v = p.value()
      p.ws()
      if (!p.atEnd()) fail('trailing text after a value')
      assign(cur, curPath, path, v)
    } catch (e) {
      if (e instanceof ParseError) e.message = `line ${idx + 1}: ${e.message}`
      throw e
    }
  })
  return root
}

const cmp = (a, b) => {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < Math.min(x.length, y.length); i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}
const sortedKeys = (t) => [...t.m.keys()].sort(cmp)

function toJson(n, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  if (n.t === 'table') {
    const ks = sortedKeys(n)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => pad + JSON.stringify(k) + ': ' + toJson(n.m.get(k), ind + 1)).join(',\n') + '\n' + end + '}'
  }
  if (n.t === 'array') {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((x) => pad + toJson(x, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  if (n.t === 'integer') return n.v
  if (n.t === 'float') return JSON.stringify(n.v)
  return JSON.stringify(n.v)
}

function keyLines(n, path, out) {
  if (n.t === 'table') {
    for (const k of sortedKeys(n)) {
      const c = n.m.get(k)
      const p = path === null ? k : path + '.' + k
      out.push(p + ' ' + c.t)
      keyLines(c, p, out)
    }
  } else if (n.t === 'array') {
    n.items.forEach((c, i) => {
      const p = path + '[' + i + ']'
      out.push(p + ' ' + c.t)
      keyLines(c, p, out)
    })
  }
}

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'json' && mode !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}
try {
  const root = parseDoc(readFileSync(0, 'utf8'))
  if (mode === 'json') process.stdout.write(toJson(root, 0) + '\n')
  else {
    const out = []
    keyLines(root, null, out)
    process.stdout.write(out.map((l) => l + '\n').join(''))
  }
} catch (e) {
  if (!(e instanceof ParseError)) throw e
  process.stderr.write('error: ' + e.message + '\n')
  process.exit(2)
}
