{"command":"cat package.json; cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']
const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = '+-*/%=<>!(){}[],;.'

class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
  }
}

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && /^[A-Za-z]$/.test(c)
const isHex = (c) => c !== undefined && /^[0-9A-Fa-f]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'
const isIdentChar = (c) => isLetter(c) || isDigit(c) || c === '_'

function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1

  const advance = () => {
    const c = cs[i++]
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') {
      col = Math.floor((col - 1) / 4) * 4 + 5
    } else col++
    return c
  }

  // digit run with single underscores between digits
  const digits = (pred) => {
    let s = ''
    if (!pred(cs[i])) return s
    while (i < n) {
      if (pred(cs[i])) s += advance()
      else if (cs[i] === '_' && pred(cs[i - 1]) && pred(cs[i + 1])) s += advance()
      else break
    }
    return s
  }

  while (i < n) {
    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      advance()
      continue
    }
    const sl = line
    const sc = col
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') advance()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      let depth = 0
      do {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated block comment')
        if (cs[i] === '/' && cs[i + 1] === '*') {
          depth++
          advance()
          advance()
        } else if (cs[i] === '*' && cs[i + 1] === '/') {
          depth--
          advance()
          advance()
        } else advance()
      } while (depth > 0)
      continue
    }
    if (c === 'r' && cs[i + 1] === '"') {
      advance()
      advance()
      let s = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const d = advance()
        if (d === '"') break
        s += d
      }
      tokens.push({ line: sl, col: sc, kind: 'rawstring', body: JSON.stringify(s) })
      continue
    }
    if (isLetter(c) || c === '_') {
      let s = ''
      while (i < n && isIdentChar(cs[i])) s += advance()
      tokens.push({ line: sl, col: sc, kind: KEYWORDS.has(s) ? 'keyword' : 'ident', body: s })
      continue
    }
    if (isDigit(c)) {
      let s = ''
      let bad = false
      const p = (cs[i + 1] || '').toLowerCase()
      if (c === '0' && (p === 'x' || p === 'b' || p === 'o')) {
        s += advance()
        s += advance()
        const pred = p === 'x' ? isHex : p === 'b' ? isBin : isOct
        const d = digits(pred)
        if (!d) bad = true
        s += d
      } else {
        s += digits(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) {
          s += advance()
          s += digits(isDigit)
        }
        if (cs[i] === 'e' || cs[i] === 'E') {
          if (isDigit(cs[i + 1])) {
            s += advance()
            s += digits(isDigit)
          } else if ((cs[i + 1] === '+' || cs[i + 1] === '-') && isDigit(cs[i + 2])) {
            s += advance()
            s += advance()
            s += digits(isDigit)
          }
        }
      }
      if (isIdentChar(cs[i])) bad = true
      if (bad) {
        while (i < n && isIdentChar(cs[i])) s += advance()
        throw new ScanError(sl, sc, `invalid number ${s}`)
      }
      tokens.push({ line: sl, col: sc, kind: 'number', body: s })
      continue
    }
    if (c === '"') {
      advance()
      let s = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const el = line
        const ec = col
        const d = advance()
        if (d === '"') break
        if (d === '\n') throw new ScanError(el, ec, 'newline in string')
        if (d !== '\\') {
          s += d
          continue
        }
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const e = advance()
        const bad = () => new ScanError(el, ec, `invalid escape \\${e}`)
        if (e === 'n') s += '\n'
        else if (e === 't') s += '\t'
        else if (e === 'r') s += '\r'
        else if (e === '\\') s += '\\'
        else if (e === '"') s += '"'
        else if (e === '0') s += '\0'
        else if (e === 'x') {
          if (!(isHex(cs[i]) && isHex(cs[i + 1]))) throw bad()
          s += String.fromCharCode(parseInt(advance() + advance(), 16))
        } else if (e === 'u') {
          if (cs[i] !== '{') throw bad()
          let j = i + 1
          let h = ''
          while (isHex(cs[j])) h += cs[j++]
          if (!h || cs[j] !== '}') throw bad()
          const v = parseInt(h, 16)
          if (v > 0x10ffff) throw bad()
          while (i <= j) advance()
          s += String.fromCodePoint(v)
        } else throw bad()
      }
      tokens.push({ line: sl, col: sc, kind: 'string', body: JSON.stringify(s) })
      continue
    }
    const two = c + (cs[i + 1] || '')
    if (PUNCT2.includes(two)) {
      advance()
      advance()
      tokens.push({ line: sl, col: sc, kind: 'punct', body: two })
      continue
    }
    if (PUNCT1.includes(c)) {
      advance()
      tokens.push({ line: sl, col: sc, kind: 'punct', body: c })
      continue
    }
    throw new ScanError(sl, sc, `unexpected character ${c}`)
  }
  return tokens
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}
try {
  const tokens = scan(readFileSync(0, 'utf8'))
  let out = ''
  if (args[0] === 'tokens') {
    for (const t of tokens) out += `${t.line}:${t.col} ${t.kind} ${t.body}\n`
  } else {
    for (const k of KINDS) out += `${k} ${tokens.filter((t) => t.kind === k).length}\n`
    out += `total ${tokens.length}\n`
  }
  process.stdout.write(out)
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${e.line}:${e.col}: ${e.message}\n`)
  process.exit(2)
}
