{"file_path":"src/cli.js","content":"import fs from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (code) => ({ k: 'e', v: code })
const num = (v) => ({ k: 'n', v })

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

// ---- sheet parsing
const input = fs.readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
const cells = new Map() // key "COL,ROW" normalized addr -> {addr, content}
const ADDR = /^([A-Za-z]{1,2})([0-9]{1,3})$/
function parseAddr(w) {
  const m = ADDR.exec(w)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  return { col: m[1].toUpperCase(), row }
}
for (let i = 0; i < lines.length; i++) {
  const t = lines[i].replace(/^[ \t]+/, '')
  if (t === '' || t[0] === '#') continue
  const m = /^[^ \t]*/.exec(t)
  const word = m[0]
  const a = parseAddr(word)
  if (!a) fail(`error: line ${i + 1}: invalid cell address ${word}`)
  const key = a.col + a.row
  if (cells.has(key)) fail(`error: line ${i + 1}: cell ${word} is declared twice`)
  const content = t.slice(word.length).replace(/^[ \t]+/, '')
  cells.set(key, { col: a.col, row: a.row, content })
}
const colCmp = (a, b) => (a.length !== b.length ? a.length - b.length : a < b ? -1 : a > b ? 1 : 0)
const sorted = [...cells.values()].sort((a, b) => colCmp(a.col, b.col) || a.row - b.row)

// ---- formula parsing
class Bad extends Error {}
function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ t: 'word', v: m[0] }); i += m[0].length
    } else if ((m = /^(<>|<=|>=|[<>=^*\/+\-(),:])/.exec(s.slice(i)))) {
      toks.push({ t: 'op', v: m[0] }); i += m[0].length
    } else throw new Bad()
  }
  return toks
}

function parseFormula(src) {
  const toks = tokenize(src)
  let p = 0
  const peek = () => toks[p]
  const isOp = (v) => toks[p] && toks[p].t === 'op' && toks[p].v === v
  function cmp() {
    let l = add()
    while (peek() && peek().t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(peek().v)) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { n: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { n: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    const t = toks[p]
    if (!t) throw new Bad()
    if (t.t === 'num') { p++; return { n: 'num', v: t.v } }
    if (t.t === 'op') {
      if (t.v !== '(') throw new Bad()
      p++
      const e = cmp()
      if (!isOp(')')) throw new Bad()
      p++
      return e
    }
    p++
    const up = t.v.toUpperCase()
    if (isOp('(')) {
      p++
      const args = []
      if (isOp(')')) throw new Bad() // calls need at least one argument syntactically
      for (;;) {
        args.push(cmp())
        if (isOp(',')) { p++; continue }
        if (isOp(')')) { p++; break }
        throw new Bad()
      }
      return { n: 'call', name: up, args }
    }
    if (up === 'TRUE') return { n: 'bool', v: true }
    if (up === 'FALSE') return { n: 'bool', v: false }
    if (isOp(':')) {
      p++
      const t2 = toks[p]
      if (!t2 || t2.t !== 'word') throw new Bad()
      p++
      return { n: 'range', a: up, b: t2.v.toUpperCase() }
    }
    return { n: 'ref', a: up }
  }
  const e = cmp()
  if (p !== toks.length) throw new Bad()
  return e
}

const parsed = new Map()
function getAst(cell) {
  if (parsed.has(cell)) return parsed.get(cell)
  let ast = null
  if (cell.content[0] === '=') {
    try { ast = parseFormula(cell.content.slice(1)) } catch (e) { if (!(e instanceof Bad)) throw e }
  }
  parsed.set(cell, ast)
  return ast
}

// ---- address helpers
function colIndex(c) {
  return c.length === 1 ? c.charCodeAt(0) - 64 : (c.charCodeAt(0) - 64) * 26 + c.charCodeAt(1) - 64
}
function colName(i) {
  if (i <= 26) return String.fromCharCode(64 + i)
  const j = i - 27
  return String.fromCharCode(65 + Math.floor(j / 26)) + String.fromCharCode(65 + (j % 26))
}
// columns A..Z (1..26), AA..ZZ (27..702) in order
function colOrder(c) { return c.length === 1 ? c.charCodeAt(0) - 64 : 26 + (c.charCodeAt(0) - 65) * 26 + c.charCodeAt(1) - 64 }
function colFromOrder(i) {
  if (i <= 26) return String.fromCharCode(64 + i)
  const j = i - 27
  return String.fromCharCode(65 + Math.floor(j / 26)) + String.fromCharCode(65 + (j % 26))
}
void colIndex; void colName

// expand range to list of {col,row}, or null if an endpoint is out of range
function expandRange(a, b) {
  const x = parseAddr(a), y = parseAddr(b)
  if (!x || !y) return null
  const c1 = colOrder(x.col), c2 = colOrder(y.col)
  const out = []
  for (let c = Math.min(c1, c2); c <= Math.max(c1, c2); c++) {
    for (let r = Math.min(x.row, y.row); r <= Math.max(x.row, y.row); r++) out.push({ col: colFromOrder(c), row: r })
  }
  return out
}

// ---- evaluation
const memo = new Map()
const INPROG = {}
function cellValue(col, row) {
  const key = col + row
  const cell = cells.get(key)
  if (!cell) return num(0)
  if (memo.has(key)) {
    const m = memo.get(key)
    return m === INPROG ? err('#CYCLE!') : m
  }
  memo.set(key, INPROG)
  const v = evalCell(cell)
  memo.set(key, v)
  return v
}
function evalCell(cell) {
  const c = cell.content
  if (c[0] === '=') {
    const ast = getAst(cell)
    if (!ast) return err('#ERR!')
    return ev(ast)
  }
  if (c === '') return num(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(c)) return num(Number(c))
  if (ERRS.includes(c)) return err(c)
  return { k: 's', v: c }
}

function toNum(v) {
  if (v.k === 'n') return v
  if (v.k === 'b') return num(v.v ? 1 : 0)
  if (v.k === 's') return err('#VALUE!')
  return v
}
function fin(x) { return Number.isFinite(x) ? num(x) : err('#DIV/0!') }

function rank(v) { return v.k === 'n' ? 0 : v.k === 's' ? 1 : 2 }
function compare(a, b) {
  const ra = rank(a), rb = rank(b)
  if (ra !== rb) return ra - rb
  if (a.k === 's') {
    const x = [...a.v], y = [...b.v]
    for (let i = 0; i < Math.min(x.length, y.length); i++) {
      const d = x[i].codePointAt(0) - y[i].codePointAt(0)
      if (d) return d
    }
    return x.length - y.length
  }
  const x = a.k === 'b' ? (a.v ? 1 : 0) : a.v
  const y = b.k === 'b' ? (b.v ? 1 : 0) : b.v
  return x < y ? -1 : x > y ? 1 : 0
}

function ev(n) {
  switch (n.n) {
    case 'num': return num(n.v)
    case 'bool': return { k: 'b', v: n.v }
    case 'range': return err('#ERR!')
    case 'ref': {
      const a = parseAddr(n.a)
      return a ? cellValue(a.col, a.row) : err('#REF!')
    }
    case 'un': {
      const v = ev(n.e)
      if (v.k === 'e') return v
      const x = toNum(v)
      if (x.k === 'e') return x
      return n.op === '-' ? num(-x.v) : x
    }
    case 'bin': {
      const l = ev(n.l), r = ev(n.r)
      if (l.k === 'e') return l
      if (r.k === 'e') return r
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        const d = compare(l, r)
        const res = n.op === '=' ? d === 0 : n.op === '<>' ? d !== 0 : n.op === '<' ? d < 0 : n.op === '<=' ? d <= 0 : n.op === '>' ? d > 0 : d >= 0
        return { k: 'b', v: res }
      }
      const a = toNum(l)
      if (a.k === 'e') return a
      const b = toNum(r)
      if (b.k === 'e') return b
      switch (n.op) {
        case '+': return fin(a.v + b.v)
        case '-': return fin(a.v - b.v)
        case '*': return fin(a.v * b.v)
        case '/': return b.v === 0 ? err('#DIV/0!') : fin(a.v / b.v)
        default: return fin(Math.pow(a.v, b.v))
      }
    }
    case 'call': return call(n)
  }
}

const VARIADIC = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG']
function call(n) {
  const { name, args } = n
  if (VARIADIC.includes(name)) {
    const vals = []
    for (const a of args) {
      if (a.n === 'range') {
        const cs = expandRange(a.a, a.b)
        if (!cs) { vals.push(err('#REF!')); continue }
        for (const c of cs) vals.push(cellValue(c.col, c.row))
      } else vals.push(ev(a))
    }
    const e = vals.find((v) => v.k === 'e')
    if (e) return e
    if (name === 'COUNT') return num(vals.filter((v) => v.k === 'n').length)
    const ns = []
    for (const v of vals) {
      const x = toNum(v)
      if (x.k === 'e') return x
      ns.push(x.v)
    }
    if (name === 'SUM') return fin(ns.reduce((s, x) => s + x, 0))
    if (name === 'AVG') return fin(ns.reduce((s, x) => s + x, 0) / ns.length)
    if (name === 'MIN') return num(Math.min(...ns))
    return num(Math.max(...ns))
  }
  if (name === 'ABS') {
    if (args.length !== 1) return err('#ERR!')
    const v = ev(args[0])
    const x = toNum(v)
    return x.k === 'e' ? x : num(Math.abs(x.v))
  }
  if (name === 'IF') {
    if (args.length !== 3) return err('#ERR!')
    const c = ev(args[0])
    if (c.k === 'e') return c
    if (c.k === 's') return err('#VALUE!')
    const t = c.k === 'b' ? c.v : c.v !== 0
    return ev(args[t ? 1 : 2])
  }
  return err('#NAME?')
}

// ---- output
function fmt(v) {
  switch (v.k) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

function collect(n, set) {
  switch (n.n) {
    case 'ref': { const a = parseAddr(n.a); if (a) set.set(a.col + a.row, a); break }
    case 'range': { const cs = expandRange(n.a, n.b); if (cs) for (const c of cs) set.set(c.col + c.row, c); break }
    case 'un': collect(n.e, set); break
    case 'bin': collect(n.l, set); collect(n.r, set); break
    case 'call': for (const a of n.args) collect(a, set); break
  }
}

const out = []
for (const cell of sorted) {
  const addr = cell.col + cell.row
  if (mode === 'values') {
    out.push(`${addr}=${fmt(cellValue(cell.col, cell.row))}`)
  } else {
    const set = new Map()
    const ast = cell.content[0] === '=' ? getAst(cell) : null
    if (ast) collect(ast, set)
    const list = [...set.values()].sort((a, b) => colCmp(a.col, b.col) || a.row - b.row)
    out.push(`${addr}:` + list.map((c) => ` ${c.col}${c.row}`).join(''))
  }
}
process.stdout.write(out.length ? out.join('\n') + '\n' : '')
